<?php
require __DIR__.'/../app/bootstrap.php';  
$page=max(1,min(100000,(int)($_GET['page'] ?? 1))); $offset=($page-1)*12; $posts=[]; $total=0;
try { $total=(int)db()->query('SELECT COUNT(*) FROM posts WHERE published=1')->fetchColumn(); $posts=query_all("SELECT * FROM posts WHERE published=1 ORDER BY created_at DESC,id DESC LIMIT 12 OFFSET $offset"); }
catch (PDOException $ex) { http_response_code(503); }
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?php seo('Câu chuyện & bài viết — Phất Quạt Họa Văn','Các bài viết và câu chuyện về quạt Chàng Sơn và hành trình dự án.','posts.php'.($page>1?'?page='.$page:'')); ?><link rel="stylesheet" href="<?= asset_url('assets/style.css') ?>"><script src="<?= asset_url('assets/app.js') ?>" defer></script></head><body><?php site_header(); ?><main class="section" id="noi-dung"><a href="<?= e(site_path('index.php')) ?>" class="back">← Trang chủ</a><h1>Câu chuyện & bài viết.</h1><div class="post-grid"><?php foreach ($posts as $post): ?><article class="post"><a href="post.php?id=<?= (int)$post['id'] ?>"><?= image_tag($post['image'],$post['title']) ?><h2><?= e($post['title']) ?></h2><p><?= e($post['excerpt']) ?></p><span>Đọc bài viết ↗</span></a></article><?php endforeach; ?></div><?php if (!$posts): ?><p><?= http_response_code()===503?'Chưa thể tải bài viết. Vui lòng thử lại sau.':'Chưa có bài viết tại trang này.' ?></p><?php endif; ?><nav class="pagination" aria-label="Phân trang bài viết"><?php if ($page>1): ?><a href="?page=<?= $page-1 ?>">← Trước</a><?php endif; ?><span>Trang <?= $page ?></span><?php if ($offset+12<$total): ?><a href="?page=<?= $page+1 ?>">Tiếp →</a><?php endif; ?></nav></main><?php site_footer(); ?></body></html>
